// Every stage retains its base silhouette; extra geometry marks Hard/Extreme.
const baseBossDrawing=drawBoss;
drawBoss=function(c,stage,x,y,size,a,t=0,hit=false){baseBossDrawing(c,stage,x,y,size,a,t,hit);const mode=typeof selectedDifficulty==='undefined'?0:modeRules()===difficultyModes[2]?2:modeRules()===difficultyModes[1]?1:0;if(!mode)return;c.save();c.translate(x,y);c.rotate(a);c.scale(size/48,size/48);c.strokeStyle=mode===1?'#ffb276':'#ffe6ac';c.fillStyle='#433544';c.lineWidth=2;const poly=points=>{c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill();c.stroke()};
 // Ten distinct attachment layouts, not a shared recolour or size change.
 const shapes=[[[26,-16],[46,-37],[37,-8]],[[10,-20],[-5,-46],[-18,-22]],[[0,-27],[10,-52],[-12,-43]],[[-20,-12],[-44,-26],[-30,9]],[[2,-20],[27,-39],[18,-8]],[[16,-20],[60,-32],[59,-13]],[[-18,-18],[-55,-40],[-30,-6]],[[20,-20],[43,-36],[38,-4]],[[35,-13],[67,-23],[53,3]],[[0,-32],[12,-65],[-13,-53]]];
 for(const side of [-1,1])poly(shapes[stage].map(([x,y])=>[x,y*side]));
 if(mode===2){const count=3+stage%3;for(let i=0;i<count;i++){const angle=t*.5+i*Math.PI*2/count+stage*.2,rx=Math.cos(angle)*(55+stage%3*4),ry=Math.sin(angle)*(55+stage%3*4);c.fillStyle=bossDesigns[stage].color;poly([[rx-6,ry],[rx,ry-10-stage%4],[rx+6,ry],[rx,ry+7]])}c.strokeStyle='#ffe7aa';c.beginPath();c.moveTo(-22,-8);c.lineTo(-8,3);c.lineTo(0,-6);c.lineTo(16,10);c.stroke();c.fillStyle='#fff4d1';for(let side of [-1,1]){c.beginPath();c.arc(-9,side*11,4,0,Math.PI*2);c.fill()}}
 const boss=view==='battle'?run?.enemies.find(e=>e.type===3&&!e.dead):null;if(stage===9&&boss){const phase=bossPhase(boss);if(phase){c.strokeStyle=phase===2?'#ff769c':'#ffcf76';c.lineWidth=3;c.beginPath();c.arc(0,0,34,0,Math.PI*2);c.stroke();for(let i=0;i<phase+2;i++)poly([[i*9-13,-26],[i*9-9,-40],[i*9-5,-26]])}}c.restore()};
function bossPatternTip(stage,mode){const tips=[
 ['경고선 후 1회 돌진','2연속 돌진 · 매 돌진 옆으로 회피','3연속 돌진 후 부채꼴 탄막'],
 ['부채꼴 1회 · 사선으로 회피','재조준 후 2회 발사','각도를 바꿔 3회 · 탄 사이 공간 활용'],
 ['얼음 고리 1회','엇갈린 얼음 고리 2회','고리 2회 후 지연 얼음 지대'],
 ['추종자 3기와 독 지대','추종자 4기 · 순차 독 지대','추종자 5기 · 단계별 독 지대'],
 ['2중 파동','3중 파동','3중 파동 후 조준탄'],
 ['십자 레이저','십자 이후 대각선 레이저','십자·대각선을 순차 발사'],
 ['회전 나선탄','회전 방향 1회 반전','회전 방향 2회 반전 · 빈 공간 유지'],
 ['원형 지뢰 · 중앙 공간 활용','시계방향 지뢰 순차 폭발','엇갈린 지뢰 2회 · 열린 방향으로 이동'],
 ['3연속 돌진','3연속 돌진 + 꼬리 탄환','돌진·꼬리 탄환 + 지연 위험 지대'],
 ['고리 → 소환 → 부채꼴','체력 50%부터 패턴을 순차 결합','체력 70%·35% 단계 전환 · 순차 복합 공격']
 ];return tips[stage][mode]+' · 붉은 경고 후 이동';}
function bossPhase(e){return run.difficulty===2?(e.hp/e.maxHp<=.35?2:e.hp/e.maxHp<=.7?1:0):run.difficulty===1&&e.hp/e.maxHp<=.5?1:0}
bossShot=function(e,a,speed=170,extra={}){if(e.dead||run.hostile.length>=400)return;speed*=modeRules().projectile;run.hostile.push({owner:e,x:e.x,y:e.y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:6,r:6,color:bossDesigns[run.stage].color,...extra})};
summonBossMinions=function(e,count){for(let i=0;i<count&&run.enemies.length<180;i++){const a=i*Math.PI*2/count,hp=(55+run.stage*12)*modeRules().hp;run.enemies.push({x:e.x+Math.cos(a)*70,y:e.y+Math.sin(a)*70,hp,maxHp:hp,type:0,r:14,speed:75*modeRules().speed,shot:3,hit:0,angle:a})}};
function queueBoss(e,delay,kind,fields={}){(e.pending??=[]).push({at:run.t+delay,kind,...fields})}
function bossFan(e,a,count=7){for(let i=0;i<count;i++)bossShot(e,a+(i-(count-1)/2)*.16,205)}
function laserSet(e,angle,delay){for(let k=0;k<2;k++)bossZone(e,{shape:'line',angle:angle+k*Math.PI/2,length:1000,width:24,delay,duration:.35})}
function mines(e,offset=0,delay=1.2){const x=run.x,y=run.y;for(let i=0;i<5;i++){const a=offset+i*Math.PI/3;bossZone(e,{x:x+Math.cos(a)*150,y:y+Math.sin(a)*150,radius:48,delay:delay+(run.difficulty?i*.23:0),duration:.4})}}
prepareBossAction=function(e){e.warn=.95;e.aim=Math.atan2(run.y-e.y,run.x-e.x);e.target={x:run.x,y:run.y};e.action=run.stage;const m=run.difficulty;if(run.stage===0||run.stage===8){e.dashLeft=e.dashLeft||(run.stage===8?3:1+m);e.warn=.9}if(run.stage===5){laserSet(e,e.aim,1.15);if(m)laserSet(e,e.aim+Math.PI/4,m===2?3:2.7)}if(run.stage===7){mines(e,0,1.2);if(m===2)queueBoss(e,3,'mines')}if(run.stage===3){for(let i=0;i<3;i++)bossZone(e,{x:run.x+(i-1)*135,y:run.y+(i%2?130:0),radius:48,delay:1.1+(m?i*.8:0),duration:2})}};
function finalPattern(e,kind){if(kind===0)bossRing(e,18,e.aim);else if(kind===1)summonBossMinions(e,5+bossPhase(e));else bossFan(e,e.aim,9)}
executeBossAction=function(e){const stage=e.action,a=e.aim,m=run.difficulty;e.cycle=(e.cycle||0)+1;if(stage===0||stage===8){e.dash=.7;e.dashAngle=a;return}if(stage===1){bossFan(e,a);if(m)queueBoss(e,1.1,'fanAim');if(m===2)queueBoss(e,2.4,'fanAim',{offset:.22})}if(stage===2){bossRing(e,16,run.t*.1,{chill:true});if(m)queueBoss(e,.8,'iceRing');if(m===2)queueBoss(e,1.3,'iceZone')}if(stage===3)summonBossMinions(e,3+m);if(stage===4){bossRing(e,12);queueBoss(e,.65,'ring',{angle:Math.PI/12});if(m)queueBoss(e,1.3,'ring',{angle:0});if(m===2)queueBoss(e,2.2,'fanAim')}if(stage===6){e.spiral=2.5+m*.55;e.spiralClock=0;e.spiralStart=run.t;e.spiralAngle=a}if(stage===9){const kind=e.cycle%3,phase=bossPhase(e);finalPattern(e,kind);if(phase)queueBoss(e,1.8,'finalWarning',{pattern:(kind+1)%3});if(phase===2)queueBoss(e,4,'finalWarning',{pattern:(kind+2)%3})}e.cool=([4,3.2,4,5.5,4.5,4.8,5,5,3.8,3.8][stage]+(stage===9?bossPhase(e)*2:0))*modeRules().cooldown};
function updateQueuedBoss(e){for(const p of e.pending||[]){if(p.done||run.t<p.at)continue;p.done=true;if(p.kind==='ring')bossRing(e,12,p.angle);if(p.kind==='iceRing')bossRing(e,16,Math.PI/16,{chill:true});if(p.kind==='iceZone')bossZone(e,{x:run.x,y:run.y,radius:65,delay:1.2,duration:1});if(p.kind==='mines')mines(e,Math.PI/6,1.2);if(p.kind==='fanAim'){e.aim=Math.atan2(run.y-e.y,run.x-e.x)+(p.offset||0);e.fanWarning=run.t+.85;queueBoss(e,.85,'fanLocked',{angle:e.aim})}if(p.kind==='fanLocked')bossFan(e,p.angle);if(p.kind==='finalWarning'){e.aim=Math.atan2(run.y-e.y,run.x-e.x);e.fanWarning=run.t+.9;queueBoss(e,.9,'finalLocked',{pattern:p.pattern,angle:e.aim})}if(p.kind==='finalLocked'){e.aim=p.angle;finalPattern(e,p.pattern)}}e.pending=(e.pending||[]).filter(p=>!p.done)}
updateBoss=function(e,dt){if(e.dead){e.pending=[];return}e.hit=Math.max(0,e.hit-dt);e.cool??=2;e.warn??=0;updateQueuedBoss(e);if(e.spiral>0){e.spiral-=dt;e.spiralClock-=dt;const elapsed=run.t-e.spiralStart,reverse=run.difficulty===0?1:run.difficulty===1?(elapsed<1.5?1:-1):(elapsed<1.2||elapsed>2.4?1:-1);e.spiralAngle+=reverse*1.9*dt;if(e.spiralClock<=0){for(let i=0;i<3;i++)bossShot(e,e.spiralAngle+i*Math.PI*2/3,145);e.spiralClock=.2}}if(e.dash>0){e.dash-=dt;e.x+=Math.cos(e.dashAngle)*440*dt;e.y+=Math.sin(e.dashAngle)*440*dt;e.angle=e.dashAngle;if(run.stage===8&&run.difficulty){e.tailClock=(e.tailClock||0)-dt;if(e.tailClock<=0){bossShot(e,e.dashAngle+Math.PI+.35,120);bossShot(e,e.dashAngle+Math.PI-.35,120);e.tailClock=.22}}if(e.dash<=0){if(run.stage===8&&run.difficulty===2)bossZone(e,{radius:65,delay:1.2,duration:.5});e.dashLeft--;if(e.dashLeft>0)prepareBossAction(e);else{e.cool=4*modeRules().cooldown;if(run.stage===0&&run.difficulty===2)queueBoss(e,.4,'fanAim')}}}else if(e.warn>0){e.warn-=dt;if(e.warn<=0)executeBossAction(e)}else{const dx=run.x-e.x,dy=run.y-e.y,d=Math.hypot(dx,dy)||1;e.angle=Math.atan2(dy,dx);if(d>220){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}e.cool-=dt;if(e.cool<=0&&d<650&&!(e.pending?.length)&&!(e.spiral>0)&&!run.bossZones.some(z=>z.owner===e))prepareBossAction(e)}if(Math.hypot(e.x-run.x,e.y-run.y)<e.r+13)damagePlayer(26*(1+run.stage*.13))};
const baseWarnings=drawBossWarnings;
drawBossWarnings=function(sx,sy){baseWarnings(sx,sy);for(const e of run.enemies)if(!e.dead&&e.fanWarning>run.t){ctx.save();ctx.translate(sx(e.x),sy(e.y));ctx.rotate(e.aim);ctx.fillStyle='#ffc98555';ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,300,-.68,.68);ctx.closePath();ctx.fill();ctx.restore()}};
const baseHazards=updateHazards;
updateHazards=function(dt){if(run.enemies.some(e=>e.type===3&&!e.dead)){run.hazards=[];return}baseHazards(dt)};
